using System;using System.IO;using System.Xml;using System.Text;using System.Collections.Generic;using System.Reflection;using UnityEngine;
public class ConsoleCmdBatchEight:ConsoleCmdAbstract {
 static int checks;static void Check(bool b,string s){checks++;if(!b)throw new Exception(s);}
 public override string[] getCommands(){return new[]{"batch8verify","batch8build","batch8save"};}public override string getDescription(){return "Automated Batch 8 asset, prefab and copied-save verification.";}
 static string Folder {get{return ModManager.GetMod("StationProbe",true).Path;}}
 static Prefab Load(){var p=new Prefab();Check(p.Load("delve_wayrest_forest",true,true,false,false),"Wayrest loads");return p;}
 public override void Execute(List<string> args,CommandSenderInfo sender){try{checks=0;string mode=args.Count>0?args[0]:"verify";
  if(mode=="build"){Build();return;}if(mode=="save"||mode=="savecheck"){Save(mode=="save");return;}
  GameObject prefab=null;foreach(var b in AssetBundle.GetAllLoadedAssetBundles())if(b.name=="fieldmatbatch08.unity3d")prefab=b.LoadAsset<GameObject>("delveFieldCraftingMat");Check(prefab!=null,"Textured mat loaded by game");
  foreach(var r in prefab.GetComponentsInChildren<MeshRenderer>()){var m=r.sharedMaterial;Check(m.mainTexture!=null,"Baked albedo for "+m.name);Check(m.mainTexture.width==64&&m.mainTexture.height==64,"Baked texture dimensions");}
  var collider=prefab.GetComponent<BoxCollider>();Check(collider.size==new Vector3(.98f,.052f,.98f),"Original mat geometry retained");
  var p=Load();var doc=new XmlDocument();doc.Load(Path.Combine(Folder,"furnishings.xml"));int stations=0;
  foreach(XmlElement e in doc.DocumentElement.ChildNodes){int x=int.Parse(e.GetAttribute("x")),y=int.Parse(e.GetAttribute("y")),z=int.Parse(e.GetAttribute("z"));var b=p.GetBlock(x,y,z);Check(b.Block.GetBlockName()==e.GetAttribute("block"),"Furnishing "+e.GetAttribute("room")+" "+x+","+y+","+z);if(b.Block is BlockWorkstation){stations++;Check(CraftingManager.GetWorkstationData(b.Block.GetBlockName())!=null,"Station crafting data");}}
  Check(stations==10,"Ten basic crafting stations/mat");Check(p.GetBlock(30,2,27).Block.GetBlockName()=="campfire","Central fire retained");
  SdtdConsole.Instance.Output("[Batch08] PASS "+checks+" native asset and furnishing checks; ten basic stations; baked mat colors; central fire retained.");
 }catch(Exception e){SdtdConsole.Instance.Output("[Batch08] FAIL "+e);}}
 static void Build(){Check(GameIO.GetUserGameDataDir().Replace('\\','/').EndsWith("/BatchEight"),"Isolated fixture required");var old=Load();var p=Load();var doc=new XmlDocument();doc.Load(Path.Combine(Folder,"furnishings.xml"));
  foreach(XmlElement e in doc.DocumentElement.ChildNodes){int x=int.Parse(e.GetAttribute("x")),y=int.Parse(e.GetAttribute("y")),z=int.Parse(e.GetAttribute("z"));var b=Block.GetBlockValue(e.GetAttribute("block"),false);Check(!b.isair,"Valid block "+e.GetAttribute("block"));Check(old.GetBlock(x,y,z).isair,"Placement is clear "+x+","+y+","+z+" existing="+old.GetBlock(x,y,z).Block.GetBlockName());b.rotation=byte.Parse(e.GetAttribute("rotation"));p.SetBlock(x,y,z,b);p.SetDensity(x,y,z,127);}
  p.AddAllChildBlocks();var collisions=new StringBuilder();for(int cy=0;cy<18;cy++)for(int cz=0;cz<60;cz++)for(int cx=0;cx<60;cx++){var cb=old.GetBlock(cx,cy,cz);if(cb.rawData!=p.GetBlock(cx,cy,cz).rawData&&!cb.isair)collisions.AppendLine(cx+","+cy+","+cz+" "+cb.Block.GetBlockName());}Check(collisions.Length==0,"Furniture footprints overlap existing blocks:\n"+collisions);
  var changes=new XmlDocument();changes.LoadXml("<changes/>");int count=0;
  for(int y=0;y<18;y++)for(int z=0;z<60;z++)for(int x=0;x<60;x++){var a=old.GetBlock(x,y,z);var b=p.GetBlock(x,y,z);if(a.rawData==b.rawData&&a.damage==b.damage)continue;Check(a.isair,"New furniture footprint clear "+x+","+y+","+z);Check(!(x>=24&&x<=36&&z>=22&&z<=33),"Central hearth square untouched");var e=changes.CreateElement("cell");foreach(var kv in new Dictionary<string,string>{{"x",x.ToString()},{"y",y.ToString()},{"z",z.ToString()},{"before",a.Block.GetBlockName()}})e.SetAttribute(kv.Key,kv.Value);changes.DocumentElement.AppendChild(e);count++;}
  // Two-block-high routes from the south gate to all room doors and steward.
  var seen=new HashSet<int>();var q=new Queue<Vector2i>();q.Enqueue(new Vector2i(30,5));seen.Add(30+5*60);
  while(q.Count>0){var v=q.Dequeue();foreach(var d in new[]{new Vector2i(1,0),new Vector2i(-1,0),new Vector2i(0,1),new Vector2i(0,-1)}){int x=v.x+d.x,z=v.y+d.y;if(x<0||z<0||x>=60||z>=60||!p.GetBlock(x,2,z).isair||!p.GetBlock(x,3,z).isair||!seen.Add(x+z*60))continue;q.Enqueue(new Vector2i(x,z));}}
  foreach(var v in new[]{new Vector2i(30,40),new Vector2i(12,30),new Vector2i(48,30),new Vector2i(13,10),new Vector2i(48,11),new Vector2i(29,49)})Check(seen.Contains(v.x+v.y*60),"Walkable room/steward "+v);
  var loc=old.location;string xml=File.ReadAllText(loc.FullPathNoExtension+".xml");Check(p.Save(loc,true),"Prefab save");File.WriteAllText(loc.FullPathNoExtension+".xml",xml);changes.Save(Path.Combine(Folder,"wayrest-changes.xml"));SdtdConsole.Instance.Output("[Batch08Build] PASS "+checks+" checks; "+count+" furnishing blocks; protected existing structures, services and fire square; all room entrances reachable.");
 }
 static void Save(bool apply){Check(GameIO.GetUserGameDataDir().Replace('\\','/').EndsWith("/BatchEight"),"Copied save only");var world=GameManager.Instance.World;Check(world.GetPlayers().Count==0,"No connected players");var manager=(RegionFileManager)typeof(ChunkProviderGenerateWorld).GetField("m_RegionFileManager",BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(world.ChunkCache.ChunkProvider);var chunks=new Dictionary<string,Chunk>();foreach(long k in manager.GetAllChunkKeys()){var c=manager.GetChunkSync(k);Check(c!=null,"Readable chunk");chunks[c.X+","+c.Z]=c;}
  var p=Load();var doc=new XmlDocument();doc.Load(Path.Combine(Folder,"wayrest-changes.xml"));var dirty=new HashSet<Chunk>();int placed=0,already=0,skipped=0,stations=0;var report=new StringBuilder();
  foreach(XmlElement e in doc.DocumentElement.ChildNodes){int x=int.Parse(e.GetAttribute("x")),y=int.Parse(e.GetAttribute("y")),z=int.Parse(e.GetAttribute("z"));int wx=x-2711,wy=y+64,wz=z-2182;Chunk c;if(!chunks.TryGetValue((wx>>4)+","+(wz>>4),out c)){skipped++;continue;}var pos=new Vector3i(wx&15,wy,wz&15);var before=c.GetBlock(pos);var after=p.GetBlock(x,y,z);
   if(before.rawData==after.rawData){already++;if(!after.ischild&&after.Block is BlockWorkstation){Check(c.GetTileEntity(pos) is TileEntityWorkstation,"Persisted station tile "+pos);stations++;}continue;}
   if(!before.isair||c.GetTileEntity(pos)!=null){skipped++;report.AppendLine("PRESERVED player change "+wx+","+wy+","+wz+" "+before.Block.GetBlockName());continue;}
   if(apply){c.SetBlockRaw(pos.x,pos.y,pos.z,after);c.SetDensity(pos.x,pos.y,pos.z,127);if(!after.ischild&&after.Block is BlockWorkstation){var te=new TileEntityWorkstation(c);te.localChunkPos=pos;c.AddTileEntity(te);stations++;}else if(!after.ischild&&after.Block is BlockCompositeTileEntity){var te=new TileEntityComposite(c,after);te.localChunkPos=pos;c.AddTileEntity(te);}dirty.Add(c);}placed++;
  }
  if(apply){foreach(var c in dirty){c.RecalcHeights();c.isModified=true;c.NeedsRegeneration=true;manager.SaveChunkSnapshot(c,true);}manager.WaitSaveDone();}else Check(placed==0,"No pending furnishings on reloaded save");
  report.AppendLine("[Batch08Save] PASS apply="+apply+" new="+placed+" already="+already+" preserved/skipped="+skipped+" stations="+stations+" dirty="+dirty.Count);File.WriteAllText(Path.Combine(Folder,apply?"save-apply.txt":"save-check.txt"),report.ToString());SdtdConsole.Instance.Output(report.ToString());
 }
}
